def destination(channel, user):
    if channel == "email":
        return user["email"]
    if channel == "sms":
        return user["phone"]
    raise ValueError("unsupported channel")

def prefix(channel):
    if channel == "email":
        return "mailto:"
    if channel == "sms":
        return "sms:"
    raise ValueError("unsupported channel")

def route(channel, user):
    return prefix(channel) + destination(channel, user)

